const std::map<std::string, TrRow> &tr_table() {
	static const std::map<std::string, TrRow> table = []() { // built once, thread-safe
		std::map<std::string, TrRow> built;
		for (const TrEntry &entry : kTrEntries) built[entry.en] = entry.row;
		return built;
	}();
	return table;
}
